m_free(struct mbuf *m)
{
  DEBUG_CALL("m_free");
  DEBUG_ARG("m = %lx", (long )m);
  if(m) {

	if (m->m_flags & M_USEDLIST)
	   remque(m);

	if (m->m_flags & M_EXT)
	   free(m->m_ext);

	if (m->m_flags & M_DOFREE) {
		m->slirp->mbuf_alloced--;
		free(m);
	} else if ((m->m_flags & M_FREELIST) == 0) {
		insque(m,&m->slirp->m_freelist);
		m->m_flags = M_FREELIST; 
	}
  } 
}

